$ErrorActionPreference = "Stop"
$basePath = $PSScriptRoot
$b64 = ""

$bytes = [System.Convert]::FromBase64String($b64)
$css = [System.Text.Encoding]::UTF8.GetString($bytes)

$fullPath = Join-Path $basePath "FinancialReports.css"
[System.IO.File]::WriteAllText($fullPath, $css, [System.Text.UTF8Encoding]::new($true))
Write-Host "Created: FinancialReports.css" -ForegroundColor Green